// API type definitions (hand-written supplements)
//
// Phase 6.4: The canonical types are auto-generated by ts-rs in
// `src/generated/`.  This file contains hand-written types that either
// (a) extend generated types with UI-only fields, (b) are not yet
// generated, or (c) are legacy types pending migration.
//
// Re-export generated types that were previously duplicated here (6-10).
// Consumers importing from `types/api` still work; new code should import
// from `generated/` directly.
export type {
  ChatRequest,
  ChatResponse,
  ToolCallInfo,
  ContextStats,
  SessionInfo,
  ToolInfo,
  ConversationInputAddress,
  ConversationInputAttempt,
  ConversationInputFact,
  ConversationInputFrontier,
  ConversationInputIdentity,
  ConversationInputOutcome,
  ConversationInputPayload,
  ConversationInputPhase,
  ConversationInputProjection,
  ConversationInputReceipt,
  ConversationInputSource,
} from '../generated';
import type {
  BackgroundCellState,
  ConversationInputFact,
  ExtensionSkillEntry,
  McpServerInfo as GeneratedMcpServerInfo,
  McpToolInfo as GeneratedMcpToolInfo,
} from '../generated';
// covered by ts-rs, or (c) represent frontend-only state.  When adding
// or changing a type, prefer updating the Rust-side serde derives and
// re-generating over hand-writing here.
//
// Bridge: `src/generated/index.ts` re-exports all generated types.
// Hand-written supplements should import from `../generated` and export
// their extensions, so consumers can `import { X } from '../types/api'`
// without knowing whether X is generated or hand-written.
//
// Known gaps (types NOT yet generated):
//   - ChatRunStatus (enum with frontend-only states like 'connecting')
//   - ApprovalRequest / InputRequest / SelectionRequest (extend generated)
//   - ExecutionRound (frontend-specific aggregation)
// These should be migrated to generated types as the Rust models stabilize.

// NOTE (6-10): The following types have identical generated counterparts and
// are imported from ../generated instead of being duplicated here:
//   ChatRequest, ChatResponse, ToolCallInfo, ContextStats, SessionInfo.
// See `generated/` for the canonical definitions.

export type ChatRunStatus =
  | 'idle'
  | 'running'
  | 'thinking'
  | 'using_tool'
  | 'waiting_approval'
  | 'waiting_input'
  | 'completed'
  | 'failed'
  | 'cancelled';

export type ToolExecutionStatus =
  'running' | 'succeeded' | 'failed' | 'cancelled' | 'timed_out' | 'interrupted' | 'unknown';

export type ToolExecutionOwner =
  { kind: 'chat'; message_id: string } | { kind: 'subagent'; subagent_run_id: string };

export type ToolFailureCategory =
  | 'invalid_arguments'
  | 'unavailable'
  | 'timeout'
  | 'cancelled'
  | 'transient'
  | 'permanent'
  | 'partial_side_effect';

export type ToolRecoveryAction =
  'correct_arguments' | 'retry' | 'restore_then_retry' | 'verify_then_retry' | 'stop';

export interface ToolFailure {
  category: ToolFailureCategory;
  recovery: ToolRecoveryAction;
  side_effect: 'none' | 'possible' | 'confirmed';
  retry_after_ms?: number;
  idempotency_key?: string;
  postcondition?: string;
}

export type ToolInvocationRewrite =
  'intervention_redirect' | 'intervention_arguments' | 'pre_tool_use_hook' | 'approval';

export interface ToolInvocation {
  requested_name: string;
  requested_args: unknown;
  name: string;
  args: unknown;
  rewrites?: ToolInvocationRewrite[];
}

export type ToolResultKind =
  | { kind_type: 'text' }
  | { kind_type: 'json' }
  | { kind_type: 'image'; mime_type: string }
  | { kind_type: 'table'; columns: string[]; rows: string[][] }
  | { kind_type: 'diff'; unified_diff: string }
  | { kind_type: 'file_reference'; path: string }
  | { kind_type: 'command_output'; exit_code?: number | null }
  | { kind_type: 'skill_activation'; name: string }
  | { kind_type: 'structured_error'; error_code: string };

export interface ToolResult {
  kind: ToolResultKind;
  success: boolean;
  output: string;
  error?: string | null;
  failure?: ToolFailure | null;
  data?: unknown | null;
  truncated: boolean;
  mime_type?: string | null;
  metadata: Record<string, string>;
}

export interface ToolExecution {
  id: string;
  call_id: string;
  owner: ToolExecutionOwner;
  workspace_id: string;
  conversation_id?: string | null;
  run_id?: string | null;
  name: string;
  args_preview: string;
  status: ToolExecutionStatus;
  started_at: number;
  finished_at?: number | null;
  duration_ms?: number | null;
  detail_ref: string;
}

export interface ToolExecutionDetailManifest {
  id: string;
  invocation: ToolInvocation;
  status: ToolExecutionStatus;
  result?: ToolResult | null;
  output_bytes: number;
}

export type ToolExecutionDetailChannel = 'stdout' | 'stderr' | 'log' | 'result';

export interface ToolExecutionDetailChunk {
  channel: ToolExecutionDetailChannel;
  text: string;
}

export interface ToolExecutionDetailPage {
  chunks: ToolExecutionDetailChunk[];
  next_cursor?: string | null;
  complete: boolean;
}

/**
 * ChatEvent — 后端推给前端的聊天事件 (P2-5 discriminated union)。
 *
 * 此前定义在 useTauriChat.ts 且未导出, chatEventHandler 只好用宽接口
 * ChatEventLike + 调用方 `as any` 强转, 失去编译期类型安全。提取为公共类型,
 * 让 handleChatEvent 直接接收 ChatEvent, 每种 type 的 payload 字段精确可查。
 */
export type ChatEvent = {
  message_key?: string;
  conversation_id?: string | null;
} & (
  | { type: 'token'; data: string }
  | { type: 'thinking_start' }
  | { type: 'thinking_end'; prompt_tokens: number; completion_tokens: number }
  | {
      type: 'llm_usage';
      model: string;
      prompt_tokens: number;
      completion_tokens: number;
      total_tokens: number;
      cached_prompt_tokens: number;
      cache_creation_prompt_tokens: number;
      usage_reported: boolean;
    }
  | {
      type: 'context_compressed';
      before_count: number;
      after_count: number;
      before_tokens: number;
      after_tokens: number;
    }
  | { type: 'chart'; spec: unknown }
  | { type: 'final_answer'; data: string }
  | { type: 'cancelled' }
  | { type: 'error'; message: string }
  | { type: 'run_status'; status: ChatRunStatus }
  | { type: 'notice'; level: 'info' | 'warning' | 'error' | string; code: string; message: string }
  | { type: 'execution_path'; observed_path: string }
  | {
      type: 'approval_request';
      request_id: string;
      tool_name: string;
      args: unknown;
      prompt: string;
    }
  | { type: 'input_request'; request_id: string; prompt: string }
  | {
      type: 'selection_request';
      request_id: string;
      prompt: string;
      options: string[];
      task_id?: string | null;
      context?: unknown;
      phase?: string | null;
    }
  | { type: 'tool_batch_start'; tool_count: number }
  | { type: 'tool_batch_end' }
  | { type: 'interrupt_prompt'; run_id: string; goal: string; new_message: string }
);

export type AgentFailureCategory =
  | 'llm'
  | 'tool'
  | 'parse'
  | 'agent'
  | 'config'
  | 'mcp'
  | 'memory'
  | 'sandbox'
  | 'runtime_state'
  | 'channel'
  | 'io'
  | 'other';

export type AgentTerminalKind = 'failed' | 'cancelled' | 'timed_out' | 'permission_denied';

export interface AgentFailure {
  category: AgentFailureCategory;
  terminal_kind: AgentTerminalKind;
  retryable: boolean;
  code: string;
  http_status: number | null;
  message: string;
}

export type ToolStreamEvent =
  | { event_type: 'progress'; message: string; percent: number | null }
  | { event_type: 'output'; channel: 'stdout' | 'stderr' | 'log'; chunk: string }
  | ({ event_type: 'complete' } & ToolResult);

export type AgentEvent =
  | { type: 'token'; data: string }
  | { type: 'think_start' }
  | { type: 'think_end'; data: { prompt_tokens: number; completion_tokens: number } }
  | {
      type: 'llm_usage';
      data: {
        model: string;
        prompt_tokens: number;
        completion_tokens: number;
        total_tokens: number;
        cached_prompt_tokens: number;
        cache_creation_prompt_tokens: number;
        usage_reported: boolean;
      };
    }
  | { type: 'budget_decision'; data: Record<string, unknown> }
  | { type: 'tool_call'; data: { call_id: string; invocation: ToolInvocation } }
  | {
      type: 'tool_stream';
      data: { call_id: string; name: string; event: ToolStreamEvent };
    }
  | { type: 'tool_result'; data: { call_id: string; name: string; result: ToolResult } }
  | { type: 'tool_batch_start'; data: { tool_count: number } }
  | { type: 'tool_batch_end' }
  | { type: 'guard_triggered'; data: { guard: string; blocked: boolean } }
  | { type: 'memory_recalled'; data: { count: number } }
  | {
      type: 'context_compressed';
      data: {
        before_count: number;
        after_count: number;
        before_tokens: number;
        after_tokens: number;
      };
    }
  | { type: 'chart'; data: { spec: unknown } }
  | { type: 'error'; data: { source: string; message: string; failure: AgentFailure } }
  | { type: 'safety_notice'; data: Record<string, unknown> }
  | { type: 'parameter_error'; data: Record<string, unknown> }
  | { type: 'final_answer'; data: string }
  | { type: 'cancelled' };

export interface AgentEventEnvelope {
  schema_version: number;
  event_id: string;
  content_hash: string;
  sequence: number;
  stream_id: string;
  conversation_id: string | null;
  run_id: string | null;
  turn_id: string;
  message_id: string | null;
  execution_id: string | null;
  parent_event_id: string | null;
  timestamp: string;
  payload: AgentEvent;
}

export type ChatDriverEvent =
  | { source: 'agent'; event: AgentEventEnvelope }
  | { source: 'execution'; event: Record<string, unknown> }
  | { source: 'turn_status'; event: { status: ChatRunStatus } }
  | { source: 'execution_path'; event: { observed_path: string } }
  | { source: 'interrupt'; event: { run_id: string; goal: string; new_message: string } }
  | { source: 'input_lifecycle'; event: ConversationInputFact }
  | {
      source: 'approval_request';
      event: { request_id: string; tool_name: string; args: unknown; prompt: string };
    }
  | { source: 'input_request'; event: { request_id: string; prompt: string } }
  | {
      source: 'selection_request';
      event: {
        request_id: string;
        prompt: string;
        options: string[];
        task_id: string | null;
        context: unknown;
        phase: string | null;
      };
    }
  | {
      source: 'context_compressed';
      event: {
        before_count: number;
        after_count: number;
        before_tokens: number;
        after_tokens: number;
      };
    }
  | { source: 'command_cell_started'; event: { cell: BackgroundCellState } }
  | { source: 'command_cell_settled'; event: { cell: BackgroundCellState } }
  | { source: 'command_cell_watch_ready'; event: { result: CommandCellWatchResult } }
  | {
      source: 'command_cell_watch_delivery_started';
      event: { acknowledgement: CommandCellWatchAcknowledgement };
    }
  | {
      source: 'command_cell_watch_acknowledged';
      event: { acknowledgement: CommandCellWatchAcknowledgement };
    };

export interface CommandCellWatchReceipt {
  execution_id: string;
  watch_generation: number;
  cell_id: string;
  workspace_id: string;
  conversation_id: string;
  run_id: string | null;
  root_turn_id: string;
  state: 'started' | 'settled' | 'cancelled' | 'failed';
  started_at: string;
  settled_at: string | null;
}

export interface CommandCellWatchResult {
  receipt: CommandCellWatchReceipt;
  cell: BackgroundCellState;
}

export interface CommandCellWatchAcknowledgement {
  execution_id: string;
  watch_generation: number;
  cell_id: string;
  workspace_id: string;
  conversation_id: string;
  root_turn_id: string;
  acknowledged_turn_id: string;
  outcome: 'drained' | 'outcome_unknown';
}

export interface ChatEventEnvelope {
  schema_version: number;
  workspace_id: string;
  event_id: string;
  content_hash: string;
  sequence: number;
  stream_id: string;
  conversation_id: string | null;
  root_turn_id: string;
  turn_id: string;
  message_id: string;
  timestamp: string;
  payload: ChatDriverEvent;
}

export interface ChatEventReplay {
  events: ChatEventEnvelope[];
  retained_earliest_cursor: number | null;
  returned_earliest_cursor: number | null;
  latest_cursor: number;
  truncated: boolean;
}

