/** 技能候选(SkillCandidateDetector 从重复模式/调试经验中检测出)。 */
export interface SkillCandidateInfo {
  name: string;
  description: string;
  sample_count: number;
  source_type: string;
  has_draft: boolean;
  activated: boolean;
  confidence: number;
}

export type EvidenceCandidateStatus = 'pending' | 'applied' | 'rejected';
export type EvidenceInboxFilter = 'pending' | 'expired' | 'applied';
export type EvidenceKind =
  | 'user_preference'
  | 'project_fact'
  | 'debugging_lesson'
  | 'error_resolution'
  | 'workflow_pattern'
  | 'skill'
  | 'memory_conflict';

export interface EvidenceRef {
  source: 'background_reviewer' | 'trigger_detector' | 'auto_memory' | 'memory_reviewer';
  source_run_id?: string;
  source_role?: string;
  source_turn?: number;
  source_memory_key?: string;
  quote: string;
}

export interface MemoryConflictMember {
  key: string;
  content: string;
  confidence: number;
  status: 'draft' | 'active' | 'superseded' | 'archived';
  recall_count: number;
  updated_at: number;
}

export interface MemoryConflictProposal {
  topic: string;
  memory_type: string;
  recommended_primary_key: string;
  members: MemoryConflictMember[];
}

export type EvidenceAction =
  { kind: 'save_memory' } | { kind: 'merge_memories'; proposal: MemoryConflictProposal };

export type EvidenceTarget =
  | { kind: 'memory'; key: string }
  | {
      kind: 'memory_merge';
      primary_key: string;
      superseded_keys: string[];
      before: Array<{ key: string; content: string; meta: unknown }>;
    };

export interface EvidenceCandidate {
  schema_version: number;
  candidate_id: string;
  fingerprint: string;
  kind: EvidenceKind;
  scope: { kind: 'user' | 'workspace' | 'session'; id: string };
  content: string;
  evidence: EvidenceRef[];
  action: EvidenceAction;
  confidence: number;
  status: EvidenceCandidateStatus;
  target?: EvidenceTarget;
  revision: number;
  created_at: string;
  updated_at: string;
  expired?: boolean;
}

export interface TestConnectionResponse {
  success: boolean;
  response?: string;
  error?: string;
  model?: string;
  auth_source?: 'input' | 'config' | 'env' | 'none' | string;
  has_auth_token?: boolean;
}
